def seed_canonical_permissions_and_backfill_roles(apps, schema_editor):
    Permission = apps.get_model('authorization', 'Permission')
    Role = apps.get_model('authorization', 'Role')

    # 1. Upsert all 144 canonical permissions
    for p in CANONICAL_PERMISSIONS:
        Permission.objects.update_or_create(
            codename=p['codename'],
            defaults={
                'name': p['name'],
                'resource': p['resource'],
                'action': p['action'],
                'category': p['category'],
                'ui_label': p['ui_label'],
                'column_index': p['column_index'],
                'display_order': p['display_order'],
                'is_preserved_enterprise': p['is_preserved_enterprise'],
                'is_active': True,
            }
        )

    # 2. Activate missing permissions (FnF & Disbursal) identified in Phase 2B.2
    missing_permissions = [
        {
            'codename': 'payroll.fnf_finalize',
            'name': 'Finalize Full and Final Settlement',
            'resource': 'payroll',
            'action': 'fnf_finalize',
            'category': 'Settlements',
            'ui_label': 'Finalize Full and Final Settlement',
            'column_index': None,
            'display_order': 0,
            'is_preserved_enterprise': True,
        },
        {
            'codename': 'payroll.disburse_configure',
            'name': 'Configure Bank Accounts & Payment Routing',
            'resource': 'payroll',
            'action': 'disburse_configure',
            'category': 'Payroll',
            'ui_label': 'Configure Bank Accounts & Payment Routing',
            'column_index': None,
            'display_order': 0,
            'is_preserved_enterprise': True,
        },
    ]
    for p in missing_permissions:
        Permission.objects.update_or_create(
            codename=p['codename'],
            defaults={
                'name': p['name'],
                'resource': p['resource'],
                'action': p['action'],
                'category': p['category'],
                'ui_label': p['ui_label'],
                'column_index': p['column_index'],
                'display_order': p['display_order'],
                'is_preserved_enterprise': p['is_preserved_enterprise'],
                'is_active': True,
            }
        )

    # 3. Quarantine test artifacts without deleting rows (preserves referential integrity)
    Permission.objects.filter(
        codename__in=['test.p', 'test.perm', 'test.perm.manage']
    ).update(is_active=False)

    # 3. Deterministically backfill role slugs and system flags scoped to organization
    org_slugs = {}
    for role in Role.objects.all().order_by('organization_id', 'id'):
        name_norm = role.name.strip().lower()
        if name_norm in ROLE_SLUG_MAP:
            base_slug, is_sys = ROLE_SLUG_MAP[name_norm]
        else:
            base_slug = slugify(role.name) or f"role-{role.id}"
            is_sys = False

        slug = base_slug
        org_id = role.organization_id
        if org_id not in org_slugs:
            org_slugs[org_id] = set()

        counter = 1
        while slug in org_slugs[org_id]:
            slug = f"{base_slug}-{counter}"
            counter += 1

        org_slugs[org_id].add(slug)
        role.slug = slug
        role.is_system = is_sys
        role.save(update_fields=['slug', 'is_system'])


def reverse_canonical_permissions_and_roles(apps, schema_editor):
    Permission = apps.get_model('authorization', 'Permission')
    # Un-quarantine test artifacts on rollback
    Permission.objects.filter(
        codename__in=['test.p', 'test.perm', 'test.perm.manage']
    ).update(is_active=True)


